const input = $('When Executed by Another Workflow').first().json;
const integrity = $('05 Integrity Check').first().json;
return [{ json: {
  status: integrity.status,
  text: $('04 Surface Pass').first().json.text,
  source_lock: $('01 Source Lock').first().json,
  audit: $('02 Discourse Audit').first().json,
  integrity,
  meta: {
    pipeline_version: '0.1.0-alpha.2',
    content_type: input.content_type || 'article'
  }
} }];
